{
  "name": "苏黎世仪器UHF系列设备",
  "name_en": "Zurich Instruments UHF Series Device",
  "manufacturer": "Zurich Instruments",
  "description": "用于连接和控制苏黎世仪器 UHF 系列仪器，支持设备连接、AWG 配置、示波采集、触发参数设置、DIO 校准、时钟与采样相关设置，以及通过数据服务器进行节点读写与数据订阅。常用于量子测控和高速电子信号实验。",
  "description_en": "Used to connect to and control Zurich Instruments UHF series instruments. It supports device connection, AWG configuration, scope acquisition, trigger setup, DIO calibration, clock and sampling settings, and node read/write plus data subscription through the data server. It is commonly used in quantum control and high-speed electronic signal experiments.",
  "tag_hints": [
    "Zurich Instruments",
    "UHF",
    "AWG control",
    "scope acquisition",
    "trigger configuration",
    "DIO calibration",
    "DAQ server",
    "quantum control"
  ],
  "actions": [
    {
      "action_name": "auto-configure_awg_file",
      "description": "从文件加载并配置 AWG 程序或波形。",
      "description_en": "Load and configure the AWG program or waveform from a file."
    },
    {
      "action_name": "auto-configure_awg_string",
      "description": "从字符串内容配置 AWG 程序或波形。",
      "description_en": "Configure the AWG program or waveform from a string."
    },
    {
      "action_name": "auto-connect_device",
      "description": "连接指定设备并初始化相关模块。",
      "description_en": "Connect to the selected device and initialize the related modules."
    },
    {
      "action_name": "auto-read_scope",
      "description": "读取示波采集数据，可在读取前启用示波功能。",
      "description_en": "Read scope acquisition data, optionally enabling the scope before reading."
    },
    {
      "action_name": "auto-restart",
      "description": "重启设备或重新初始化设备连接。",
      "description_en": "Restart the device or reinitialize the device connection."
    },
    {
      "action_name": "auto-idn",
      "description": "查询设备身份信息。",
      "description_en": "Query the device identification information."
    },
    {
      "action_name": "auto-set_trigger_mode",
      "description": "设置触发模式。",
      "description_en": "Set the trigger mode."
    },
    {
      "action_name": "auto-set_trigger_level",
      "description": "设置触发电平。",
      "description_en": "Set the trigger level."
    },
    {
      "action_name": "auto-set_trigger_ext",
      "description": "设置外部触发相关参数。",
      "description_en": "Set external trigger related parameters."
    },
    {
      "action_name": "auto-set_trigger_src",
      "description": "设置触发源。",
      "description_en": "Set the trigger source."
    },
    {
      "action_name": "auto-set_trigger_slope",
      "description": "设置触发边沿方向。",
      "description_en": "Set the trigger slope."
    },
    {
      "action_name": "auto-set_trigger_coupling",
      "description": "设置触发耦合方式。",
      "description_en": "Set the trigger coupling mode."
    },
    {
      "action_name": "auto-set_time_scale",
      "description": "设置时间刻度。",
      "description_en": "Set the time scale."
    },
    {
      "action_name": "auto-set_channel_scale",
      "description": "设置通道刻度。",
      "description_en": "Set the channel scale."
    },
    {
      "action_name": "auto-do_single_shot",
      "description": "执行单次采集。",
      "description_en": "Perform a single-shot acquisition."
    },
    {
      "action_name": "auto-set_averaging",
      "description": "设置或启用平均采集。",
      "description_en": "Set or enable averaging."
    },
    {
      "action_name": "auto-set_format_real",
      "description": "设置实数格式数据输出。",
      "description_en": "Set real-valued data output format."
    },
    {
      "action_name": "auto-set_average_count",
      "description": "设置平均次数。",
      "description_en": "Set the averaging count."
    },
    {
      "action_name": "auto-sync",
      "description": "与设备服务器同步设置或数据状态。",
      "description_en": "Synchronize settings or data state with the device server."
    },
    {
      "action_name": "auto-do_get_screenshot",
      "description": "获取仪器或示波界面的截图。",
      "description_en": "Capture a screenshot from the instrument or scope interface."
    },
    {
      "action_name": "auto-get_channel_data",
      "description": "读取指定通道的数据。",
      "description_en": "Read data from the selected channel."
    },
    {
      "action_name": "auto-is_averaging_complete",
      "description": "查询平均采集是否完成。",
      "description_en": "Check whether averaging is complete."
    },
    {
      "action_name": "auto-set_maximum_rate",
      "description": "设置最大数据采集或传输速率。",
      "description_en": "Set the maximum data acquisition or transfer rate."
    },
    {
      "action_name": "auto-connect_server",
      "description": "连接到数据服务器。",
      "description_en": "Connect to the data server."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接设备或服务器。",
      "description_en": "Reconnect to the device or server."
    },
    {
      "action_name": "auto-load_settings",
      "description": "加载已保存的设备设置。",
      "description_en": "Load saved device settings."
    },
    {
      "action_name": "auto-features",
      "description": "查询设备支持的功能特性。",
      "description_en": "Query the features supported by the device."
    },
    {
      "action_name": "auto-setd",
      "description": "写入双精度数值节点。",
      "description_en": "Write a double-precision value node."
    },
    {
      "action_name": "auto-seti",
      "description": "写入整数节点。",
      "description_en": "Write an integer value node."
    },
    {
      "action_name": "auto-setv",
      "description": "写入向量或数组节点。",
      "description_en": "Write a vector or array node."
    },
    {
      "action_name": "auto-geti",
      "description": "读取整数节点。",
      "description_en": "Read an integer value node."
    },
    {
      "action_name": "auto-getd",
      "description": "读取双精度数值节点。",
      "description_en": "Read a double-precision value node."
    },
    {
      "action_name": "auto-getv",
      "description": "读取向量或数组节点。",
      "description_en": "Read a vector or array node."
    },
    {
      "action_name": "auto-find",
      "description": "查找匹配的设备节点。",
      "description_en": "Find a matching device node."
    },
    {
      "action_name": "auto-finds",
      "description": "查找多个匹配的设备节点。",
      "description_en": "Find multiple matching device nodes."
    },
    {
      "action_name": "auto-subs",
      "description": "订阅数据节点或数据流。",
      "description_en": "Subscribe to a data node or data stream."
    },
    {
      "action_name": "auto-unsubs",
      "description": "取消订阅数据节点或数据流。",
      "description_en": "Unsubscribe from a data node or data stream."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询已订阅的数据。",
      "description_en": "Poll the subscribed data."
    },
    {
      "action_name": "auto-on",
      "description": "开启设备功能、通道或输出。",
      "description_en": "Turn on a device function, channel, or output."
    },
    {
      "action_name": "auto-off",
      "description": "关闭设备功能、通道或输出。",
      "description_en": "Turn off a device function, channel, or output."
    },
    {
      "action_name": "auto-extclk",
      "description": "设置或切换外部时钟参考。",
      "description_en": "Set or switch the external clock reference."
    },
    {
      "action_name": "auto-sampleclk",
      "description": "设置采样时钟。",
      "description_en": "Set the sample clock."
    },
    {
      "action_name": "auto-mode",
      "description": "设置设备工作模式。",
      "description_en": "Set the device operating mode."
    },
    {
      "action_name": "auto-direct",
      "description": "设置直通或直接信号路径模式。",
      "description_en": "Set the direct or bypass signal path mode."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准 DIO 协议相关参数。",
      "description_en": "Calibrate DIO protocol related parameters."
    },
    {
      "action_name": "auto-dio_snapshot",
      "description": "获取当前 DIO 状态快照。",
      "description_en": "Capture a snapshot of the current DIO state."
    },
    {
      "action_name": "auto-awg_dio_snapshot",
      "description": "获取与 AWG 相关的 DIO 状态快照。",
      "description_en": "Capture a snapshot of the AWG-related DIO state."
    },
    {
      "action_name": "auto-dio_testmode",
      "description": "设置或启用 DIO 测试模式。",
      "description_en": "Set or enable the DIO test mode."
    },
    {
      "action_name": "auto-onOffMultiple",
      "description": "同时开启或关闭多个功能或通道。",
      "description_en": "Turn multiple functions or channels on or off at once."
    }
  ]
}

